import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 32
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    ))

    identifier = re.compile(r"[A-Z][A-Z0-9_]*")
    header_index = None
    first_wide = None
    first_multifield = None
    first_nonblank = None

    for index, record in enumerate(records):
        if not any(value.strip() for value in record):
            continue

        if first_nonblank is None:
            first_nonblank = index
        if first_multifield is None and len(record) > 1:
            first_multifield = index
        if first_wide is None and len(record) == expected_width:
            first_wide = index

        # The header begins with machine identifiers, unlike the data records.
        prefix = [value.strip() for value in record[:4]]
        if (
            len(prefix) == 4
            and all(identifier.fullmatch(value) for value in prefix)
            and any("_" in value for value in prefix)
            and len(set(prefix)) == len(prefix)
        ):
            header_index = index
            break

    if header_index is None:
        for candidate in (first_wide, first_multifield, first_nonblank):
            if candidate is not None:
                header_index = candidate
                break
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Preserve surplus cells in extra columns instead of discarding them.
    used_names = set(columns)
    while len(columns) < width:
        position = len(columns) + 1
        name = f"column_{position}"
        suffix = 2
        while name in used_names:
            name = f"column_{position}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
